package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamAgreeModalsBank1 {
  private const val T = "Subject-Verb Agreement"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("Neither the captain nor the players ___ ready for the coin toss.", "were", "was", "is", "has", "With 'neither...nor', the verb agrees with the closer plural subject 'players'."),
    q("Neither the players nor the captain ___ pleased with the referee's decision.", "was", "were", "are", "have", "Closer subject 'captain' is singular, so singular 'was' is correct."),
    q("Either my sister or my parents ___ attending the school concert.", "are", "is", "was", "has", "Closer subject 'my parents' is plural, requiring 'are'."),
    q("Either the teachers or the principal ___ going to address the assembly.", "is", "are", "were", "have", "Closer subject 'the principal' is singular, taking 'is'."),
    q("Not only the violinist but also the singers ___ praised by the panel.", "were", "was", "is", "has been", "'Not only...but also' matches the closer subject 'singers' -> 'were'."),
    q("Not only the books but also the laptop ___ missing from the desk.", "was", "were", "are", "have been", "Closer subject 'the laptop' is singular -> 'was'."),
    q("The bouquet of fresh jasmines ___ placed neatly on the table.", "was", "were", "are", "have been", "True head noun 'The bouquet' is singular, taking 'was'."),
    q("A basket of ripe mangoes ___ sent to our grandparents in Kurunegala.", "was", "were", "are", "have been", "Singular head noun 'A basket' determines singular verb 'was'."),
    q("The quality of these handmade baskets ___ truly impressive.", "is", "are", "were", "have", "Subject 'The quality' is singular, regardless of plural 'baskets'."),
    q("The price of basic vegetables ___ risen sharply this month.", "has", "have", "are", "were", "Singular subject 'The price' takes 'has'."),
    q("Each of the thirty participants ___ awarded a merit certificate.", "was", "were", "are", "have been", "'Each of + plural noun' always takes a singular verb 'was'."),
    q("Every student in Grade 10 and 11 ___ required to bring an atlas.", "is", "are", "were", "have", "'Every + singular noun' always takes a singular verb 'is'."),
    q("Everyone in the science society ___ excited about the field trip.", "seems", "seem", "are seeming", "were seeming", "Indefinite pronoun 'Everyone' is singular and takes 'seems'."),
    q("Somebody ___ left an umbrella beside the library entrance.", "has", "have", "are", "were", "'Somebody' is always grammatically singular -> 'has'."),
    q("Nobody in the examination hall ___ allowed to speak.", "is", "are", "were", "have been", "'Nobody' takes a singular verb 'is'."),
    q("Everything in the exhibition stall ___ arranged in neat rows.", "was", "were", "are", "have", "'Everything' is singular and takes 'was'."),
    q("Ten kilometres ___ a long distance to walk on a hot afternoon.", "is", "are", "were", "have", "Distances viewed as a single unit take a singular verb 'is'."),
    q("Five thousand rupees ___ enough to buy all the required stationery.", "is", "are", "were", "have", "Sums of money treated as a whole take singular 'is'."),
    q("Three hours ___ too short for painting the entire wall mural.", "is", "are", "were", "have", "Time periods treated as a single unit take singular 'is'."),
    q("The news about the national scholarship results ___ spread fast.", "has", "have", "are", "were", "'News' ends in -s but is an uncountable singular noun -> 'has'."),
    q("Mathematics ___ sharp logical thinking and daily practice.", "requires", "require", "are requiring", "have required", "Academic subjects ending in -ics take singular verb 'requires'."),
    q("Physics ___ my younger brother's favourite subject in O/L.", "is", "are", "were", "have been", "Subject name 'Physics' is singular -> 'is'."),
    q("Measles ___ a contagious illness common among young children.", "is", "are", "were", "have been", "Disease names like 'Measles' and 'Mumps' take singular 'is'."),
    q("Bread and butter ___ his favourite breakfast before school.", "is", "are", "were", "have been", "Two items forming a single dish take singular 'is'."),
    q("Rice and curry ___ served every afternoon at the school canteen.", "is", "are", "were", "have been", "'Rice and curry' as one meal takes a singular verb 'is'."),
    q("Slow and steady ___ the race, according to the fable.", "wins", "win", "are winning", "were winning", "Paired ideas treated as one concept take singular 'wins'."),
    q("The principal, along with the teachers, ___ inspecting the hall.", "is", "are", "were", "have been", "Phrases with 'along with' do not make a singular subject plural."),
    q("Saman, as well as his two sisters, ___ learning classical music.", "is", "are", "were", "have been", "With 'as well as', the verb agrees with the first noun 'Saman'."),
    q("The coach, together with the athletes, ___ leaving for Galle today.", "is", "are", "were", "have", "Prepositional 'together with' leaves subject 'The coach' singular."),
    q("A pair of spectacles ___ lying beside the thick dictionary.", "was", "were", "are", "have been", "'A pair of' is singular and takes 'was'."),
    q("His new pair of sports shoes ___ very comfortable for running.", "is", "are", "were", "have", "Singular head 'pair' requires singular verb 'is'."),
    q("These spectacles ___ too loose to wear while playing cricket.", "are", "is", "was", "has been", "Without 'a pair of', 'spectacles' is plural and takes 'are'."),
    q("The scissors on the tailor's desk ___ extremely sharp.", "are", "is", "was", "has been", "'Scissors' without 'a pair of' always takes a plural verb 'are'."),
    q("My trousers ___ freshly ironed for tomorrow's assembly.", "are", "is", "was", "has been", "'Trousers' is a plural-only noun taking 'are'."),
    q("Two-thirds of the forest reserve ___ protected by wildlife laws.", "is", "are", "were", "have been", "Fractions agree with the following noun: singular 'reserve' -> 'is'."),
    q("Half of the apples in the crate ___ already ripe.", "are", "is", "was", "has been", "Plural countable noun after 'Half of' ('apples') takes 'are'."),
    q("Half of the mango juice ___ spilled on the kitchen counter.", "was", "were", "are", "have", "Uncountable 'mango juice' after 'Half of' takes singular 'was'."),
    q("The number of students learning coding ___ increased this year.", "has", "have", "are", "were", "'The number of + plural noun' takes a singular verb 'has'."),
    q("A number of Grade 11 students ___ volunteering at the book fair.", "are", "is", "was", "has been", "'A number of' means 'several' and takes plural 'are'."),
    q("The furniture in the new library hall ___ crafted from teak.", "is", "are", "were", "have been", "Uncountable noun 'furniture' always takes singular 'is'."),
    q("The luggage belonging to the tourists ___ loaded onto the coach.", "was", "were", "are", "have", "Uncountable 'luggage' requires singular verb 'was'."),
    q("Both Kasun and Tharindu ___ selected for the debating final.", "were", "was", "is", "has been", "'Both...and' always forms a plural subject -> 'were'."),
    q("Kamal and his best friend ___ planning a trip to Ella.", "are", "is", "was", "has been", "Two subjects joined by 'and' take plural 'are'."),
    q("The poet and dramatist ___ arrived to judge the contest.", "has", "have", "are", "were", "One article ('The') before two titles means one person -> 'has'."),
    q("The poet and the dramatist ___ both speaking at the seminar.", "are", "is", "was", "has", "Two separate articles ('The... and the...') indicate two people -> 'are'."),
    q("One of my closest friends ___ moving to Kandy next month.", "is", "are", "were", "have", "'One of + plural noun' has singular head 'One' -> 'is'."),
    q("One of the laboratory microscopes ___ needing urgent repair.", "is", "are", "were", "have been", "Singular head 'One' takes singular verb 'is'."),
    q("There ___ several interesting reference books on the top shelf.", "are", "is", "was", "has been", "In 'There + be', verb agrees with real subject 'books' -> 'are'."),
    q("There ___ a bottle of clean water inside my school bag.", "is", "are", "were", "have been", "Real subject 'a bottle' is singular -> 'is'."),
    q("Here ___ the official invitation cards for the parents.", "are", "is", "was", "has been", "Plural subject 'cards' after 'Here' takes 'are'."),
    q("Many a student ___ dreamed of winning a national medal.", "has", "have", "are", "were", "'Many a + singular noun' always takes a singular verb 'has'."),
    q("More than one candidate ___ scored full marks in Test 1.", "has", "have", "are", "were", "'More than one + singular noun' takes singular 'has'."),
    q("The police ___ investigating the midnight burglary near the bank.", "are", "is", "was", "has been", "'The police' is always treated as plural in standard English -> 'are'."),
    q("The cattle ___ grazing peacefully near the village tank.", "were", "was", "is", "has been", "'Cattle' is a plural noun taking plural verb 'were'."),
    q("A flock of white egrets ___ resting in the paddy field.", "was", "were", "are", "have", "Collective noun 'A flock' treated as a single unit takes 'was'."),
    q("The committee ___ divided in their opinions about the venue.", "are", "is", "was", "has", "When collective members act individually ('their opinions'), use 'are'."),
    q("The committee ___ decided to hold the sports meet in July.", "has", "have", "are", "were", "Collective noun acting as a unified body takes singular 'has'."),
    q("None of the milk ___ wasted after the morning assembly.", "was", "were", "are", "have been", "'None of' with uncountable 'milk' takes singular 'was'."),
    q("Some of the photographs in the album ___ faded over time.", "have", "has", "is", "was", "'Some of' with plural 'photographs' takes plural 'have'."),
    q("Plenty of fresh drinking water ___ available at the camp.", "is", "are", "were", "have been", "'Plenty of' with uncountable 'water' takes singular 'is'."),
    q("Plenty of volunteers ___ ready to help clean the beach.", "are", "is", "was", "has been", "'Plenty of' with plural 'volunteers' takes plural 'are'."),
    q("All of the students ___ already handed in their assignments.", "have", "has", "is", "was", "'All of' + plural countable 'students' takes plural 'have'."),
    q("All of the advice in that handbook ___ very practical.", "is", "are", "were", "have been", "'All of' + uncountable 'advice' takes singular 'is'."),
    q("Walking in the morning ___ blood circulation and fitness.", "improves", "improve", "are improving", "have improved", "A gerund phrase acting as subject ('Walking...') takes singular 'improves'."),
    q("To forgive others freely ___ great strength of character.", "requires", "require", "are requiring", "have required", "An infinitive subject ('To forgive...') takes singular 'requires'."),
    q("Reading storybooks and writing essays ___ my favourite hobbies.", "are", "is", "was", "has been", "Two gerund subjects joined by 'and' take plural 'are'."),
    q("What the children need most ___ patience and encouragement.", "is", "are", "were", "have", "Noun clause 'What the children need' takes singular verb 'is'."),
    q("'Great Expectations' ___ written by Charles Dickens.", "was", "were", "are", "have been", "Book titles, even plural in form, always take singular 'was'."),
    q("The United Nations ___ working to protect global biodiversity.", "is", "are", "were", "have", "Organization names take a singular verb 'is'."),
    q("Statistics ___ an important branch of applied mathematics in Grade 11.", "is", "are", "were", "have been", "When referring to the academic discipline, 'Statistics' takes singular 'is'."),
    q("Economics ___ closely linked with everyday household budgeting.", "is", "are", "were", "have been", "Academic field 'Economics' takes singular 'is'."),
    q("No student and no teacher ___ permitted to enter without a pass.", "is", "are", "were", "have been", "Subjects preceded by 'each' or 'no' take singular 'is'."),
    q("Every man, woman, and child ___ rescued before the flood rose.", "was", "were", "are", "have been", "Multiple singular subjects introduced by 'Every' take singular 'was'."),
    q("Who ___ the leader of the Grade 11 science club this term?", "is", "are", "were", "have", "Asking about a single leader takes 'is'."),
    q("Neither of these two keys ___ the locked store-room door.", "fits", "fit", "fitting", "are fitting", "'Neither of' is grammatically singular and takes 'fits'."),
    q("Either of the two routes ___ safe to travel before sunset.", "is", "are", "were", "have been", "'Either of' takes a singular verb 'is'."),
    q("Much of the ancient mural painting ___ faded over centuries.", "has", "have", "are", "were", "'Much of' with uncountable/singular noun takes 'has'."),
    q("Few of the invited guests ___ arrived at the hall yet.", "have", "has", "is", "was", "'Few of' is always plural and takes 'have'."),
    q("Little ___ known about the ancient ruins before excavations began.", "was", "were", "are", "have been", "'Little' as pronoun for uncountable amount takes singular 'was'."),
    q("Several of our classmates ___ won scholarships to study music.", "have", "has", "is", "was", "'Several of' always takes a plural verb 'have'."),
    q("The rich ___ not always realize how hard villagers work.", "do", "does", "is", "has", "'The + adjective' referring to a group of people takes plural 'do'."),
    q("The elderly ___ extra care and respect from the community.", "deserve", "deserves", "is deserving", "was deserving", "'The elderly' acts as a plural group noun taking 'deserve'."),
    q("Sixty percent of the exam paper ___ comprehension and writing.", "tests", "test", "are testing", "were testing", "Percentage of a singular noun ('paper') takes singular 'tests'."),
    q("Forty percent of the library books ___ printed in Sinhala.", "are", "is", "was", "has been", "Percentage of plural noun ('books') takes plural 'are'."),
    q("The majority of our school's athletes ___ every morning.", "practise", "practises", "is practising", "has practised", "'Majority of + plural noun (athletes)' takes plural 'practise'."),
    q("A large amount of plastic waste ___ collected during the clean-up.", "was", "were", "are", "have been", "'A large amount of' + uncountable noun takes singular 'was'."),
    q("A large number of saplings ___ planted around the playground.", "were", "was", "is", "has been", "'A large number of' + plural noun takes plural 'were'."),
    q("Your luggage, along with your passport, ___ checked at the counter.", "was", "were", "are", "have been", "Uncountable 'luggage' remains singular regardless of additions."),
    q("The captain, accompanied by the crew, ___ greeted by the crowd.", "was", "were", "are", "have been", "'Accompanied by' does not change singular subject 'captain'."),
    q("The students who ___ the quiz will represent the province.", "win", "wins", "is winning", "has won", "Relative pronoun 'who' refers to plural 'students' -> 'win'."),
    q("The girl who ___ the violin at assembly is my neighbour.", "plays", "play", "are playing", "were playing", "Relative pronoun 'who' refers to singular 'The girl' -> 'plays'."),
    q("She is one of the writers who ___ inspiring young readers.", "are", "is", "was", "has been", "Antecedent of 'who' is plural 'writers', so use 'are'."),
    q("He is the only one of the finalists who ___ in Kurunegala.", "lives", "live", "are living", "have lived", "'The only one' makes the singular 'one' the antecedent -> 'lives'."),
    q("The jury ___ unable to reach a unanimous decision yesterday.", "was", "were", "are", "have been", "Acting as one collective body takes singular 'was'."),
    q("Data from the weather station ___ severe wind speeds tonight.", "indicates", "indicate", "are indicate", "were indicate", "In modern usage, 'Data' as a mass noun takes singular 'indicates'."),
    q("Athletics ___ a popular sport in Sri Lankan national schools.", "is", "are", "were", "have been", "Sports/fields ending in -ics take singular 'is'."),
    q("Either you or he ___ responsible for locking the main gate.", "is", "are", "were", "have", "Verb agrees with closer singular pronoun 'he' -> 'is'."),
    q("Neither he nor I ___ aware of the sudden change in timetable.", "am", "is", "are", "were", "Verb agrees with closer subject 'I' -> 'am'.")
  )
}
